CREATE SCHEMA IF NOT EXISTS "public";
CREATE TABLE "User" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UserApiCredential" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"encryptedGeminiKey" JSONB,"encryptedGroqKey" JSONB,"geminiConfigured" BOOLEAN NOT NULL DEFAULT false,"groqConfigured" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "UserApiCredential_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RefreshToken" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3) NOT NULL,"revoked" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "RefreshToken_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InterviewProject" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InterviewProject_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InterviewSession" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"projectId" TEXT,"title" TEXT NOT NULL,"type" TEXT NOT NULL,"company" TEXT NOT NULL,"position" TEXT NOT NULL,"round" TEXT NOT NULL DEFAULT '',"style" TEXT NOT NULL DEFAULT 'standard',"personality" TEXT NOT NULL DEFAULT 'real',"difficulty" TEXT,"model" TEXT NOT NULL,"durationSec" INTEGER,"status" TEXT NOT NULL DEFAULT 'active',"startTime" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endTime" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "InterviewSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InterviewMessage" ("id" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"role" TEXT NOT NULL,"content" TEXT NOT NULL,"board" TEXT,"meta" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InterviewMessage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InterviewQuestion" ("id" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"question" TEXT NOT NULL,"questionType" TEXT,"sequenceNumber" INTEGER NOT NULL,"topic" TEXT,"difficulty" TEXT,"hintsUsed" INTEGER NOT NULL DEFAULT 0,"solved" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InterviewQuestion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InterviewResponse" ("id" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"questionId" TEXT,"messageId" TEXT,"userResponse" TEXT,"aiFeedback" TEXT,"score" DOUBLE PRECISION,"durationMs" INTEGER,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InterviewResponse_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InterviewAnalytics" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"overallScore" DOUBLE PRECISION,"communicationScore" DOUBLE PRECISION,"technicalScore" DOUBLE PRECISION,"confidenceScore" DOUBLE PRECISION,"strengths" JSONB,"weaknesses" JSONB,"improvementSuggestions" JSONB,"report" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InterviewAnalytics_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TopicStat" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"topic" TEXT NOT NULL,"attempts" INTEGER NOT NULL DEFAULT 0,"average" DOUBLE PRECISION NOT NULL DEFAULT 0,"hintsTotal" INTEGER NOT NULL DEFAULT 0,"lastSeen" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TopicStat_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "UserApiCredential_userId_key" ON "UserApiCredential"("userId"); CREATE UNIQUE INDEX "RefreshToken_tokenHash_key" ON "RefreshToken"("tokenHash"); CREATE INDEX "RefreshToken_userId_expiresAt_idx" ON "RefreshToken"("userId","expiresAt"); CREATE INDEX "InterviewProject_userId_createdAt_idx" ON "InterviewProject"("userId","createdAt"); CREATE INDEX "InterviewSession_userId_createdAt_idx" ON "InterviewSession"("userId","createdAt"); CREATE INDEX "InterviewSession_userId_status_idx" ON "InterviewSession"("userId","status"); CREATE INDEX "InterviewMessage_sessionId_createdAt_idx" ON "InterviewMessage"("sessionId","createdAt"); CREATE INDEX "InterviewQuestion_sessionId_createdAt_idx" ON "InterviewQuestion"("sessionId","createdAt"); CREATE UNIQUE INDEX "InterviewQuestion_sessionId_sequenceNumber_key" ON "InterviewQuestion"("sessionId","sequenceNumber"); CREATE UNIQUE INDEX "InterviewResponse_messageId_key" ON "InterviewResponse"("messageId"); CREATE INDEX "InterviewResponse_sessionId_createdAt_idx" ON "InterviewResponse"("sessionId","createdAt"); CREATE UNIQUE INDEX "InterviewAnalytics_sessionId_key" ON "InterviewAnalytics"("sessionId"); CREATE INDEX "InterviewAnalytics_userId_createdAt_idx" ON "InterviewAnalytics"("userId","createdAt"); CREATE UNIQUE INDEX "TopicStat_userId_topic_key" ON "TopicStat"("userId","topic");
ALTER TABLE "UserApiCredential" ADD CONSTRAINT "UserApiCredential_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "RefreshToken" ADD CONSTRAINT "RefreshToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "InterviewProject" ADD CONSTRAINT "InterviewProject_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "InterviewSession" ADD CONSTRAINT "InterviewSession_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "InterviewSession" ADD CONSTRAINT "InterviewSession_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "InterviewProject"("id") ON DELETE SET NULL; ALTER TABLE "InterviewMessage" ADD CONSTRAINT "InterviewMessage_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "InterviewSession"("id") ON DELETE CASCADE; ALTER TABLE "InterviewQuestion" ADD CONSTRAINT "InterviewQuestion_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "InterviewSession"("id") ON DELETE CASCADE; ALTER TABLE "InterviewResponse" ADD CONSTRAINT "InterviewResponse_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "InterviewSession"("id") ON DELETE CASCADE; ALTER TABLE "InterviewResponse" ADD CONSTRAINT "InterviewResponse_questionId_fkey" FOREIGN KEY ("questionId") REFERENCES "InterviewQuestion"("id") ON DELETE SET NULL; ALTER TABLE "InterviewAnalytics" ADD CONSTRAINT "InterviewAnalytics_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "InterviewAnalytics" ADD CONSTRAINT "InterviewAnalytics_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "InterviewSession"("id") ON DELETE CASCADE; ALTER TABLE "TopicStat" ADD CONSTRAINT "TopicStat_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE;
